#!/usr/bin/env python3
from __future__ import annotations
import argparse, base64, gzip, hashlib, shutil, subprocess, tempfile
from pathlib import Path

V121_SHA256 = "1a44487de886d59f612cfbd083cacadf872ad56d0db13604cbf8af0056c600c2"
V96_SHA256 = "dc0938fa82952e6599b04725f1e397ac1f317a0ddffaefbae204e265171b0a22"
V97_SHA256 = "3597c6e8f0f32139cb84eece0552e733b969f1578c7a7530c9898a539c9101fb"
PATCH_V121_TO_V96_GZ_B64 = ""
V97_OVERLAY_GZ_B64 = ""

def sha256(path: Path) -> str:
    return hashlib.sha256(path.read_bytes()).hexdigest()

def apply_patch(target: Path, encoded: str) -> None:
    data = gzip.decompress(base64.b64decode(encoded))
    with tempfile.NamedTemporaryFile(suffix='.patch', delete=False) as f:
        f.write(data); name=f.name
    try:
        subprocess.run(['patch','--batch','--silent',str(target),name],check=True)
    finally:
        Path(name).unlink(missing_ok=True)

def main() -> int:
    ap=argparse.ArgumentParser()
    ap.add_argument('--v121', required=True)
    ap.add_argument('--out-dir', default='eval_agents/v97')
    args=ap.parse_args()
    src=Path(args.v121); out=Path(args.out_dir); out.mkdir(parents=True,exist_ok=True)
    if sha256(src)!=V121_SHA256: raise RuntimeError(f'v121 sha256 mismatch: {sha256(src)}')
    v96=out/'v96_champion_lead11_milkshops2.py'; v97=out/'v97_candidate_actual_trade_race.py'
    shutil.copyfile(src,v96); apply_patch(v96,PATCH_V121_TO_V96_GZ_B64)
    if sha256(v96)!=V96_SHA256: raise RuntimeError(f'v96 sha256 mismatch: {sha256(v96)}')
    shutil.copyfile(v96,v97)
    with v97.open('ab') as f: f.write(gzip.decompress(base64.b64decode(V97_OVERLAY_GZ_B64)))
    if sha256(v97)!=V97_SHA256: raise RuntimeError(f'v97 sha256 mismatch: {sha256(v97)}')
    compile(v96.read_text(encoding='utf-8'),str(v96),'exec')
    compile(v97.read_text(encoding='utf-8'),str(v97),'exec')
    print('v96',sha256(v96)); print('v97',sha256(v97))
    return 0

if __name__=='__main__': raise SystemExit(main())
